SELECT d.entity_kind || ' ' || coalesce(nullif(d.entity_name, ''), '(одиночный)') || ' — пометка «' || m.value || '» вне реестра: этому виду она не разрешена' AS detail FROM project_documents d CROSS JOIN scheme($1) m LEFT JOIN scheme($1) h ON h.role = 'marker.home' AND h.value = d.entity_kind WHERE d.project_id = $1 AND m.role = 'marker.unresolved' AND position(m.value in d.content) > 0 AND h.value IS NULL ORDER BY 1
